export const CHARGE_LIMIT_PCT=80,DEGRADE_PER_CYCLE=.025,CAPACITY_FLOOR_PCT=70,HEALTH_GOOD_THRESHOLD=80,THROUGHPUT_CAP=9999900,BATTERY_HEALTH_KEY="ios-desktop:battery-health-v1",HEALTH_STATUS=Object.freeze({GOOD:"good",SERVICE:"service"}),SUGGESTION=Object.freeze({LIMIT:"limit",SERVICE:"service"}),HEALTH_DEFAULTS=Object.freeze({totalChargePct:0,limitOn:!1,ts:0});export function clampCycles(e){if(typeof e=="boolean")return 0;const t=Number(e);return!Number.isFinite(t)||t<=0?0:Math.min(9999900/100,Math.floor(t))}export function clampThroughput(e){if(typeof e=="boolean")return 0;const t=Number(e);return!Number.isFinite(t)||t<=0?0:Math.min(9999900,Math.floor(t))}export function capacityAfterCycles(e){const r=clampCycles(e)*25/1e3;return Math.max(70,100-r)}export function healthStatus(e){const t=Number(e);return Number.isFinite(t)?t>=80?{key:HEALTH_STATUS.GOOD,label:"\u826F\u597D"}:{key:HEALTH_STATUS.SERVICE,label:"\u5EFA\u8BAE\u68C0\u4FEE"}:{key:HEALTH_STATUS.SERVICE,label:"\u5EFA\u8BAE\u68C0\u4FEE"}}export function cyclesFromThroughput(e){return Math.floor(clampThroughput(e)/100)}export function recordChargeDelta(e,t,r){const o=e&&typeof e=="object"?e:{...HEALTH_DEFAULTS};if(r!==!0||!Number.isFinite(t)||t<=0)return o;const n=clampThroughput((Number(o.totalChargePct)||0)+t);return{...o,totalChargePct:n}}export function chargeHoldReached(e,t){if(t!==!0)return!1;const r=Number(e);return Number.isFinite(r)&&r>=80}export function chargingSuggestion(e,t,r){return healthStatus(e).key===HEALTH_STATUS.SERVICE?{id:SUGGESTION.SERVICE,text:"\u7535\u6C60\u5065\u5EB7\u5EA6\u504F\u4F4E\uFF0C\u5EFA\u8BAE\u9001\u68C0\u66F4\u6362\u7535\u6C60"}:r===!0&&t!==!0?{id:SUGGESTION.LIMIT,text:"\u5F00\u542F\u5145\u7535\u4E0A\u9650\uFF0880%\uFF09\u6709\u52A9\u4E8E\u5EF6\u7F13\u7535\u6C60\u8001\u5316"}:null}export function parseHealthState(e){let t=e;if(typeof e=="string")try{t=JSON.parse(e)}catch{return{...HEALTH_DEFAULTS}}return!t||typeof t!="object"||Array.isArray(t)?{...HEALTH_DEFAULTS}:{totalChargePct:clampThroughput(t.totalChargePct),limitOn:t.limitOn===!0,ts:Number.isFinite(Number(t.ts))?Math.max(0,Math.floor(Number(t.ts))):0}}export function serializeHealthState(e){return JSON.stringify(parseHealthState(e))}
